module WhbThermo.Tests.LiquidGoldenTests

open System
open System.Globalization
open System.IO
open Xunit
open Ganfoss.ROP
open WhbThermo.Domain
open WhbThermo.Liquids

/// Saturated-liquid campaign against CoolProp, generated by
/// tools/generate_golden.py.
///
/// Only points inside each correlation's own validity range are graded. Outside
/// it a fit is not expected to hold, and grading it there would either fail good
/// data or force tolerances so wide they catch nothing. Points outside are still
/// evaluated, to confirm they warn rather than fail silently.
module private Reference =

    let private read name =
        let file = Path.Combine(AppContext.BaseDirectory, "reference", name)
        if not (File.Exists file) then [||]
        else
            let lines = File.ReadAllLines file
            let header = lines.[0].Split(',')
            lines |> Array.skip 1
                  |> Array.map (fun l -> Array.zip header (l.Split(',')) |> Map.ofArray)

    let number (row: Map<string, string>) key =
        Double.Parse(row.[key], CultureInfo.InvariantCulture)

    let rows = read "coolprop-liquids.csv"

open Reference

let private db =
    match Dippr.load () with
    | Success (d, _) -> d
    | Failure msgs -> failwith (msgs |> List.map string |> String.concat "; ")

/// Tolerances set from the measured spread over 453 in-range comparisons:
/// rho 0.8 % worst, hvap 3.8 %, cp 6.0 %, k 9.5 %. Viscosity is the exception,
/// and n-pentane is excluded from it as a known bad source record.
let private tolerance = dict [ "rho", 0.03; "mu", 0.15; "k", 0.15; "cp", 0.10; "hvap", 0.08 ]

/// Species and properties with a documented reason to be excluded.
let private excluded =
    dict [ ("nC5H12", "mu"), "known bad source record, flagged in liquid-properties.json" ]

let private inRange (species: Dippr.LiquidSpecies) name (t: float<K>) =
    match Map.tryFind name species.Correlations with
    | Some c ->
        let above = match c.TMin with Some lo -> t >= lo | None -> true
        let below = match c.TMax with Some hi -> t <= hi | None -> true
        above && below
    | None -> false

[<Fact>]
let ``saturated liquid properties track CoolProp inside the fit ranges`` () =
    Assert.True(rows.Length > 0, "run tools/generate_golden.py first")

    let failures = ResizeArray<string>()
    let mutable compared = 0

    for row in rows do
        let key = row.["species"]
        match Dippr.find db key with
        | Failure _ -> ()
        | Success (s, _) ->
            let t = number row "T_K" * 1.0<K>
            let tr = row.["Tr"]

            let check label name (evaluate: unit -> Thermo<float>) reference =
                if inRange s name t && not (excluded.ContainsKey((key, label))) then
                    match evaluate () with
                    | Failure _ -> ()
                    | Success (ours, _) ->
                        compared <- compared + 1
                        let deviation = abs (ours - reference) / abs reference
                        if deviation > tolerance.[label] then
                            failures.Add
                                $"{key} {label} at Tr {tr}: {deviation:P1} "
                                + $"(ours {ours:g4}, CoolProp {reference:g4})"

            check "rho" "liquidMolarDensity"
                  (fun () -> Dippr.liquidDensity s t >>= fun v -> ok (float v))
                  (number row "rho_kg_m3")
            check "mu" "liquidViscosity"
                  (fun () -> Dippr.liquidViscosity s t >>= fun v -> ok (float v))
                  (number row "mu_Pas")
            check "k" "liquidConductivity"
                  (fun () -> Dippr.liquidConductivity s t >>= fun v -> ok (float v))
                  (number row "k_W_mK")
            check "cp" "liquidMolarHeatCapacity"
                  (fun () -> Dippr.liquidHeatCapacity s t >>= fun v -> ok (float v))
                  (number row "cp_J_kgK")
            check "hvap" "heatOfVaporisation"
                  (fun () -> Dippr.heatOfVaporisation s t)
                  (number row "hvap_J_kg")

    Assert.True(compared > 250, $"only {compared} in-range comparisons made")
    Assert.True(failures.Count = 0, String.Join("\n", failures))

/// Negative control. If a swapped species still passes, the tolerances are
/// decoration rather than a test.
[<Fact>]
let ``the comparison detects a swapped species`` () =
    let benzene =
        match Dippr.find db "C6H6" with
        | Success (s, _) -> s
        | Failure _ -> failwith "benzene missing"

    let mismatches =
        rows
        |> Array.filter (fun r -> r.["species"] = "nC10H22")
        |> Array.sumBy (fun row ->
            let t = number row "T_K" * 1.0<K>
            match Dippr.liquidDensity benzene t with
            | Success (ours, _) ->
                let deviation =
                    abs (float ours - number row "rho_kg_m3") / number row "rho_kg_m3"
                if deviation > tolerance.["rho"] then 1 else 0
            | Failure _ -> 0)

    Assert.True(mismatches > 0,
                "benzene passed against n-decane reference density; tolerance too loose")

/// Outside the fit range the library must still be well behaved: either a
/// warning with a finite number, or an explicit failure. Never a silent NaN.
[<Fact>]
let ``evaluation outside the fit range never returns a silent non-finite value`` () =
    let failures = ResizeArray<string>()
    for row in rows do
        let key = row.["species"]
        match Dippr.find db key with
        | Failure _ -> ()
        | Success (s, _) ->
            let t = number row "T_K" * 1.0<K>
            for name, evaluate in
                [ "liquidViscosity", (fun () -> Dippr.liquidViscosity s t >>= fun v -> ok (float v))
                  "liquidConductivity", (fun () -> Dippr.liquidConductivity s t >>= fun v -> ok (float v))
                  "liquidMolarDensity", (fun () -> Dippr.liquidDensity s t >>= fun v -> ok (float v)) ] do
                match evaluate () with
                | Failure _ -> ()
                | Success (v, warnings) ->
                    if Double.IsNaN v || Double.IsInfinity v then
                        failures.Add $"{key} {name} at {t}: non-finite {v}"
                    if not (inRange s name t) && List.isEmpty warnings then
                        failures.Add $"{key} {name} at {t}: outside range without a warning"

    Assert.True(failures.Count = 0, String.Join("\n", failures))

/// Cross-check between two independent parts of the library: the DIPPR water
/// correlations and IAPWS-IF97 must agree on saturated liquid water. They come
/// from completely different sources, so agreement is meaningful.
[<Fact>]
let ``DIPPR water agrees with IAPWS-IF97`` () =
    let steam =
        match WhbThermo.Steam.If97.load () with
        | Success (m, _) -> m
        | Failure msgs -> failwith (msgs |> List.map string |> String.concat "; ")

    let water =
        match Dippr.find db "H2O" with
        | Success (s, _) -> s
        | Failure _ -> failwith "water missing"

    let failures = ResizeArray<string>()
    for pBar in [ 1.0; 5.0; 20.0; 50.0 ] do
        match WhbThermo.Steam.If97.saturatedAt steam (pBar * 1.0<bar>) with
        | Failure _ -> ()
        | Success (state, _) ->
            let t = state.SaturationTemperature
            match Dippr.liquidHeatCapacity water t with
            | Success (cp, _) ->
                let deviation = abs (float cp / 1000.0 - state.Liquid.Cp) / state.Liquid.Cp
                if deviation > 0.05 then
                    failures.Add $"{pBar} bar: cp {deviation:P1} apart "
                                 + $"(DIPPR {float cp / 1000.0:F3}, IF97 {state.Liquid.Cp:F3})"
            | Failure _ -> ()

    Assert.True(failures.Count = 0, String.Join("\n", failures))
